import ServiceManagement
import SwiftUI
struct SettingsView:View{@ObservedObject var model:MenuBarManager;@AppStorage("appearance") var appearance="跟随系统";@State var login=SMAppService.mainApp.status == .enabled;@State var error:String?
 var body:some View{Form{Section("菜单栏项目"){Toggle("CPU",isOn:$model.showCPU);Toggle("Memory",isOn:$model.showMemory);Toggle("Network",isOn:$model.showNetwork);Toggle("Disk",isOn:$model.showDisk);Toggle("显示图标",isOn:$model.showIcon);Toggle("显示百分比 / 数值",isOn:$model.showPercent)};Section("外观与更新"){Picker("外观",selection:$appearance){Text("跟随系统").tag("跟随系统");Text("浅色").tag("浅色");Text("深色").tag("深色")};Picker("刷新频率",selection:$model.interval){Text("0.5 秒").tag(0.5);Text("1 秒").tag(1.0);Text("2 秒").tag(2.0);Text("5 秒").tag(5.0)}.onChange(of:model.interval){model.start()};HStack{Text("字体大小");Slider(value:$model.font,in:10...16,step:1);Text("\(Int(model.font)) pt")}};Section("系统"){Toggle("开机启动",isOn:Binding(get:{login},set:setLogin));if let error{Text(error).foregroundStyle(.red)}};Section{Text("所有数据仅在本机采样。未使用第三方库。磁盘驱动未公开 I/O 计数时速度显示为 0。")}}.formStyle(.grouped).frame(width:480,height:520).preferredColorScheme(appearance=="浅色" ? .light:appearance=="深色" ? .dark:nil)}
 func setLogin(_ value:Bool){do{if value{try SMAppService.mainApp.register()}else{try SMAppService.mainApp.unregister()};login=value;error=nil}catch{self.error=error.localizedDescription}}}
